// A libFuzzer entry point for the container parser.

import RasterWebPCore

/// Parses one input generated by libFuzzer.
@_cdecl("LLVMFuzzerTestOneInput")
public func fuzzContainer(_ data: UnsafePointer<UInt8>?, _ count: Int) -> CInt {
    let bytes = UnsafeBufferPointer(start: data, count: count)
    _ = try? WebPImageInfo(parsing: bytes.span)
    return 0
}
